pub type SurfaceModifiers = Vec<SurfaceModifier>;

/// A range of text in UTF-16 code units, as the DOM counts: start at or before end; start = end is a caret.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
