/// macOS: an IOSurface. The compositor wraps it as a Metal texture. In the same process it finds the surface by id among those the host holds; across processes the surface's Mach send right travels out of band and id checks it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceIoSurfaceHandle {
    pub kind: SurfaceIoSurfaceHandleKind,
    /// The IOSurfaceID (IOSurfaceGetID).
    pub id: u64,
    /// Across processes: the index of the surface's Mach send right (IOSurfaceCreateMachPort) among the message's out-of-band rights.
    #[serde(rename = "portIndex", default, skip_serializing_if = "Option::is_none")]
    pub port_index: Option<u64>,
}

/// Windows: an NT shared handle to a D3D11 texture (IDXGIResource1::CreateSharedHandle), opened on the compositor's device. The value is valid in the sending process; the compositor duplicates it from a process it started.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceD3d11Handle {
    pub kind: SurfaceD3d11HandleKind,
    /// The handle's value in the sending process.
    pub handle: u64,
    /// The texture has an IDXGIKeyedMutex: the producer releases it with key 1 when the frame is written, the compositor acquires key 1 to read and releases with key 0. Without one, the producer flushes and waits for its GPU before it attaches.
    #[serde(rename = "keyedMutex")]
    pub keyed_mutex: bool,
}

/// One plane of a DMA-BUF: its fd (by index among the message's out-of-band fds), the bytes per row and where the plane starts in that fd.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceDmaBufPlane {
    #[serde(rename = "fdIndex")]
    pub fd_index: u64,
    pub stride: u64,
    pub offset: u64,
}

/// Linux: a DMA-BUF, imported as a Vulkan image (Wayland and X11 alike). bgra8 is the fourcc AR24 (or XR24 when opaque), rgba8 AB24 (or XB24). One plane for a linear or plain tiled layout; a modifier with auxiliary planes (compression) brings up to four.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceDmaBufHandle {
    pub kind: SurfaceDmaBufHandleKind,
    /// The DRM fourcc code as its four characters: AR24, XR24, AB24, XB24.
    pub fourcc: String,
    /// The DRM format modifier in hexadecimal, as a string because it needs 64 bits: 0x0 is linear, 0xffffffffffffff (DRM_FORMAT_MOD_INVALID) leaves the layout to the driver.
    pub modifier: String,
    pub planes: Vec<SurfaceDmaBufPlane>,
}

/// Where a texture's memory is: one shape per OS. File descriptors and Mach rights it names travel out of band beside the message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum SurfaceTextureHandle {
    SurfaceIoSurface(SurfaceIoSurfaceHandle),
    SurfaceD3d11(SurfaceD3d11Handle),
    SurfaceDmaBuf(SurfaceDmaBufHandle),
}

/// A shared texture a surface draws into. id names one of the producer's textures (it may rotate several); generation counts the allocations behind that id, so the compositor imports a texture once per id and generation and samples its import for every later frame.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceTexture {
    pub id: u64,
    pub generation: u64,
    /// In pixels.
    pub width: u64,
    /// In pixels.
    pub height: u64,
    pub format: SurfaceFormat,
    pub handle: SurfaceTextureHandle,
}

/// When the compositor gives an attached texture back. after-copy: it copies the damage into a texture of its own and releases at once, before composing (a producer whose texture is valid only briefly, such as an engine's paint callback). when-replaced: it samples the texture itself and releases it when a later frame replaces it on screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum SurfaceReleaseWhen {
    #[serde(rename = "after-copy")]
    AfterCopy,
    #[serde(rename = "when-replaced")]
    WhenReplaced,
}

/// A new frame: the texture it is in, what changed, and when the compositor gives the texture back. The producer has finished writing it (GPU work flushed and done, the keyed mutex released, or a fence given) and does not write it again until its release.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceAttach {
    pub r#type: SurfaceAttachType,
    pub surface: SurfaceId,
    /// Counts up with every attach of this surface; the release names it.
    pub frame: u64,
    pub texture: SurfaceTexture,
    /// What changed since the surface's previous frame, in the texture's pixels; a whole-texture change is one rectangle that covers it. A texture the compositor has not imported, or a new size, counts as wholly damaged.
    pub damage: Vec<SurfacePixelRect>,
    pub release: SurfaceReleaseWhen,
    /// DMA-BUF only: a sync_file fd, by index among the out-of-band fds, that signals when the producer's writes are done. Without it, the kernel's implicit sync on the DMA-BUF applies.
    #[serde(
        rename = "fenceFdIndex",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub fence_fd_index: Option<u64>,
}

/// The compositor is done reading the texture of this frame: the producer may write it again. Every attach gets exactly one release, in frame order, unless the surface sleeps, dies or is destroyed first.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceRelease {
    pub r#type: SurfaceReleaseType,
    pub surface: SurfaceId,
    pub frame: u64,
    /// DMA-BUF only: a sync_file fd, by index among the out-of-band fds, that signals when the compositor's reads are done; the producer waits on it before writing. Without it, the reads are done.
    #[serde(
        rename = "fenceFdIndex",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub fence_fd_index: Option<u64>,
}

/// The most frames per second the surface may attach: the display's rate while it is in front, lower while it is in the background. A surface that paints only on change paints less. A hidden surface paints nothing whatever its pace.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
